#import "KARPAExporter.h"
static NSString *CSV(NSString *s){NSString *x=[s isKindOfClass:NSString.class]?s:@"";return [NSString stringWithFormat:@"\"%@\"",[x stringByReplacingOccurrencesOfString:@"\"" withString:@"\"\""]];}
BOOL KARPAWriteCSVAndDependencyReport(NSDictionary *r,NSString *dir,NSError **e){NSMutableString *csv=[NSMutableString stringWithString:@"class,kind,selector,typeEncoding,imp,image,direct\n"];for(NSDictionary *c in r[@"runtime"][@"classes"]?:@[]){for(NSDictionary *m in [c[@"methods"]?:@[] arrayByAddingObjectsFromArray:c[@"classMethods"]?:@[]]){[csv appendFormat:@"%@,%@,%@,%@,%@,%@,%@\n",CSV(c[@"name"]),CSV(m[@"kind"]),CSV(m[@"selector"]),CSV(m[@"typeEncoding"]),CSV(m[@"imp"]),CSV(m[@"image"]),CSV([m[@"direct"] description])];}}if(![csv writeToFile:[dir stringByAppendingPathComponent:@"runtime_dump.csv"] atomically:YES encoding:NSUTF8StringEncoding error:e])return NO;NSMutableDictionary *dep=[@{ @"schema":@"karpa.dependencies.v1",@"evidence":@"STATIC_BINARY_CONFIRMED",@"images":@[] } mutableCopy];NSMutableArray *images=[NSMutableArray array];for(NSDictionary *i in r[@"images"]?:@[]) [images addObject:@{ @"path":i[@"path"]?:@"",@"uuid":i[@"uuid"]?:@"",@"dependencies":i[@"dependencies"]?:@[] }];dep[@"images"]=images;NSData *d=[NSJSONSerialization dataWithJSONObject:dep options:NSJSONWritingPrettyPrinted error:e];return d&&[d writeToFile:[dir stringByAppendingPathComponent:@"dependency_report.json"] options:NSDataWritingAtomic error:e];}
